type Product = { id: number; sku: string; name: string; image_url?: string; category: string; category_ref?: number | null; subcategory?: number | null; brand?: number | null; description?: string; barcode?: string; selling_price: string; cost_price: string; stock_quantity: number; reorder_level: number; is_active: boolean };
