type CustomerDraft = Omit<Customer, "id">;
type CartLine = { product: Product; quantity: number };
type PaymentDraft = { method: "cash" | "card" | "transfer" | "other"; amount: string; reference: string };
type ReferenceRecord = { id: number; name: string; slug?: string; description: string; is_active: boolean; display_order?: number; product_count: number; category?: number; logo_url?: string };
type InvoiceRecord = { id: number; invoice_number: string; sale_id: number; customer_name: string; customer_email: string; total: string; amount_paid: string; balance_due: string; status: string; created_at: string };
type TransactionRecord = { id: number; reference: string; kind: string; amount: string; payment_method: string; invoice_number: string | null; cashier_name: string | null; created_at: string };
type UserPreferences = { theme: "light" | "dark"; notify_low_stock: boolean; notify_sales: boolean; updated_at: string };
type UserProfile = { id: number; username: string; email: string; first_name: string; last_name: string; is_superuser: boolean; groups: string[] };
type RefundRecord = { id: number; sale: number; invoice_number: string; status: "pending" | "approved" | "rejected"; reason: string; return_to_stock: boolean; subtotal: string; tax_amount: string; total: string; requested_by: number; requested_by_name: string; reviewed_by_name: string | null; created_at: string; reviewed_at: string | null; items: { id: number; sale_item: number; product_name: string; product_sku: string; quantity: number; subtotal: string }[] };
