type RegisterShift = { id: number; status: "open" | "closed"; opening_float: string; expected_cash: string; counted_cash: string | null; difference: string | null; opened_at: string; closed_at: string | null; movements: { id: number; kind: string; amount: string; note: string; created_at: string }[] };
