type BusinessSettings = { business_name: string; address: string; phone: string; email: string; currency_code: string; tax_rate: string; require_open_shift: boolean; allow_negative_stock: boolean; updated_at: string };
type PosNotification = { id: number; kind: string; title: string; body: string; target: string; is_read: boolean; created_at: string; read_at: string | null };
type GlobalSearchItem = { id: number; title: string; detail: string; target: string };
