const money = (v: string | number) => { const amount = Number(v || 0); const currency = document.documentElement.dataset.currency || "LKR"; return currency === "LKR" ? `Rs. ${amount.toLocaleString("en-LK", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : new Intl.NumberFormat("en", { style: "currency", currency, minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount); };
